// ---------- permanent song numbers ----------
// Every song has a number (song.no). It never changes and is never given to another song: adding, deleting,
// importing or restoring songs does not renumber anything. data.songSeq remembers the highest number ever used.
const goodNo = n => Number.isInteger(n) && n > 0;
function numberSongs() {
  const songs = data.songs || [];
  let seq = goodNo(data.songSeq) ? data.songSeq : 0, changed = false;
  for (const s of songs) if (goodNo(s.no) && s.no > seq) seq = s.no;
  for (const t of TRASH) if (goodNo(t.no) && t.no > seq) seq = t.no; // a deleted song keeps its number too, in case it is restored
  const used = new Set(), fresh = [];
  for (const s of songs) { if (goodNo(s.no) && !used.has(s.no)) used.add(s.no); else fresh.push(s); }
  // first time ever: number the whole library alphabetically, so the numbers read like the index of a hymn book
  if (fresh.length === songs.length && songs.length > 1) fresh.sort((a, b) => String(a.title || '').localeCompare(String(b.title || ''), undefined, { sensitivity: 'base', numeric: true }));
  for (const s of fresh) { s.no = ++seq; changed = true; }
  if (data.songSeq !== seq) { data.songSeq = seq; changed = true; }
  return changed;
}
